public class RemoveNthFromEnd {
    static class ListNode {
        int val;
        ListNode next;
        ListNode(int v) { val = v; }
    }

    public ListNode removeNthFromEnd(ListNode head, int n) {
        ListNode dummy = new ListNode(0); // 哑结点：让头结点也有前驱
        dummy.next = head;
        ListNode fast = dummy, slow = dummy;

        // fast 先走 n 步，制造间距
        for (int i = 0; i < n; i++) {
            fast = fast.next;
        }

        // 同步前进，fast 到末尾时 slow 在待删前驱
        while (fast.next != null) {
            fast = fast.next;
            slow = slow.next;
        }

        // 删除：跳过待删结点
        slow.next = slow.next.next;

        return dummy.next; // 可能头结点已被删
    }
}
